const decimal T2 = 100_000_000m;
const decimal T3 = 500_000_000m;

decimal Tiered(decimal s)
{
    decimal c = Math.Min(s, T2) * 0.02m;
    if (s > T2) c += (Math.Min(s, T3) - T2) * 0.05m;
    if (s > T3) c += (s - T3) * 0.08m;
    return c;
}

decimal Flat(decimal s) => s switch
{
    < T2 => s * 0.02m,
    <= T3 => s * 0.05m,
    _ => s * 0.08m,
};

Console.WriteLine((long)(Tiered(501_000_000m) - Tiered(500_000_000m)));
Console.WriteLine((long)(Flat(501_000_000m) - Flat(500_000_000m)));

